code_sketch:
#[derive(Clone, PartialEq, Debug)]
enum Payment {
    Card { number: String },
    Transfer { iban: String },
}

fn describe(p: &Payment) -> &str {
    match p {                        // exhaustive: a new variant is a build error
        Payment::Card { number } => number,
        Payment::Transfer { iban } => iban,
    }
}

