mod private { pub trait Sealed {} }

pub trait Payment: private::Sealed {          // sealed: only this crate can impl
    fn describe(&self) -> &str;
}

pub struct Card { pub number: String }
impl private::Sealed for Card {}
impl Payment for Card {
    fn describe(&self) -> &str { &self.number }
}
